// AWS Certified Cloud Practitioner (CLF-C02) practice question bank.
// Domains and weights mirror the real, currently-published CLF-C02 exam guide:
//   Domain 1: Cloud Concepts (24%)
//   Domain 2: Security and Compliance (30%)
//   Domain 3: Cloud Technology and Services (34%)
//   Domain 4: Billing, Pricing, and Support (12%)

export const DOMAINS = [
  { key: "concepts", label: "Cloud Concepts", weightPct: 24 },
  { key: "security", label: "Security & Compliance", weightPct: 30 },
  { key: "technology", label: "Cloud Technology & Services", weightPct: 34 },
  { key: "billing", label: "Billing, Pricing & Support", weightPct: 12 },
];

const questions = [
  // ── DOMAIN 1: CLOUD CONCEPTS (24%) ──────────────────────────────────────────
  { id: 1, domain: "concepts", question: "A company wants to expand into new geographic markets quickly without purchasing and shipping physical servers to each new location. Which benefit of AWS Cloud computing does this scenario primarily illustrate?", options: ["Economies of scale", "Global reach", "Elasticity", "High availability"], answer: 1, explanation: "AWS's global network of Regions lets companies deploy applications close to users in new markets within minutes, instead of the months required to build physical data centers — this is the global reach benefit." },
  { id: 2, domain: "concepts", question: "Which AWS Cloud benefit allows a company to automatically increase compute capacity during a flash sale and then reduce it afterward, paying only for what is used?", options: ["Elasticity", "Agility", "Economies of scale", "Global reach"], answer: 0, explanation: "Elasticity is the ability to automatically scale resources up or down to match demand, so you pay only for the capacity you actually use." },
  { id: 3, domain: "concepts", question: "What does 'agility' mean as a benefit of cloud computing?", options: ["The ability to provision new IT resources quickly, reducing the time needed to make them available to developers", "The ability to negotiate lower hardware prices due to bulk purchasing", "The ability to run workloads across multiple Availability Zones", "The ability to encrypt data automatically"], answer: 0, explanation: "Agility refers to the increased speed and ease with which you can develop, test, and launch applications, since cloud resources can be provisioned in minutes instead of weeks." },
  { id: 4, domain: "concepts", question: "A traditional on-premises data center requires a company to purchase enough servers to handle its busiest day of the year, even though that capacity sits idle most of the time. Which cloud benefit directly addresses this problem?", options: ["Trade capital expense for variable expense", "Increased speed and agility", "Global reach", "Loose coupling"], answer: 0, explanation: "Instead of investing heavily upfront in data centers and servers (CapEx) before knowing usage patterns, cloud computing lets companies pay only for the IT resources they consume as a variable operating expense." },
  { id: 5, domain: "concepts", question: "Which statement best describes 'economies of scale' as an AWS Cloud benefit?", options: ["Because AWS aggregates usage from hundreds of thousands of customers, it can achieve higher economies of scale, which translates into lower pay-as-you-go prices", "Each customer receives a dedicated physical data center reserved exclusively for them", "AWS guarantees that prices will never increase for any service", "Economies of scale means every AWS account receives the same amount of compute capacity"], answer: 0, explanation: "Aggregating demand from a huge number of customers allows AWS to operate at massive scale and pass the resulting cost savings on to customers through lower prices." },
  { id: 6, domain: "concepts", question: "The AWS Well-Architected Framework is organized around six pillars. Which of the following is NOT one of them?", options: ["Operational Excellence", "Performance Efficiency", "Sustainability", "Market Competitiveness"], answer: 3, explanation: "The six pillars are Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, and Sustainability. 'Market Competitiveness' is not one of them." },
  { id: 7, domain: "concepts", question: "Which pillar of the AWS Well-Architected Framework focuses on running and monitoring systems to deliver business value, and continually improving supporting processes and procedures?", options: ["Operational Excellence", "Reliability", "Cost Optimization", "Security"], answer: 0, explanation: "The Operational Excellence pillar covers running and monitoring systems, and continually improving processes, including automating changes and responding to events." },
  { id: 8, domain: "concepts", question: "Which Well-Architected pillar focuses on the ability of a system to recover from infrastructure or service disruptions and dynamically acquire computing resources to meet demand?", options: ["Reliability", "Performance Efficiency", "Security", "Cost Optimization"], answer: 0, explanation: "The Reliability pillar covers a workload's ability to perform its intended function correctly and consistently, including recovering quickly from failures." },
  { id: 9, domain: "concepts", question: "Which pillar of the Well-Architected Framework is concerned with using computing resources efficiently to meet requirements and maintaining that efficiency as demand changes and technologies evolve?", options: ["Performance Efficiency", "Operational Excellence", "Reliability", "Sustainability"], answer: 0, explanation: "Performance Efficiency focuses on using IT and computing resources efficiently, for example by selecting the right instance types or storage options for a workload." },
  { id: 10, domain: "concepts", question: "The Cost Optimization pillar of the Well-Architected Framework is primarily concerned with which of the following?", options: ["Running systems to deliver business value at the lowest possible price point", "Encrypting all data both at rest and in transit", "Maximizing the number of Availability Zones used by a workload", "Minimizing the number of IAM users in an account"], answer: 0, explanation: "Cost Optimization is about avoiding unnecessary costs, understanding spending over time, and selecting the right number and type of resources to meet business needs without overspending." },
  { id: 11, domain: "concepts", question: "Which Well-Architected pillar was added to address minimizing the environmental impacts of running cloud workloads?", options: ["Sustainability", "Security", "Reliability", "Operational Excellence"], answer: 0, explanation: "The Sustainability pillar focuses on minimizing the environmental impacts of running cloud workloads, such as energy consumption and efficiency." },
  { id: 12, domain: "concepts", question: "A finance team is comparing running a data center on-premises versus using AWS. Buying physical servers upfront is an example of which type of expenditure?", options: ["Capital expenditure (CapEx)", "Operational expenditure (OpEx)", "Variable expenditure", "Elastic expenditure"], answer: 0, explanation: "Capital expenditure (CapEx) refers to upfront spending on physical infrastructure, such as purchasing servers, which must be paid regardless of how much the infrastructure is actually used." },
  { id: 13, domain: "concepts", question: "Paying a monthly AWS bill based on actual resource consumption, with no large upfront hardware purchase, is an example of which type of expenditure?", options: ["Operational expenditure (OpEx)", "Capital expenditure (CapEx)", "Fixed expenditure", "Sunk cost"], answer: 0, explanation: "Cloud computing converts large upfront capital expenses into smaller, variable operational expenses that scale with actual usage." },
  { id: 14, domain: "concepts", question: "What is the key difference between scalability and elasticity in cloud computing?", options: ["Scalability is the ability to increase resource capacity to meet demand, while elasticity also includes automatically decreasing capacity when demand drops", "Scalability only applies to storage, while elasticity only applies to compute", "Scalability means resources never change, while elasticity means resources are always changing", "There is no difference; the terms are interchangeable"], answer: 0, explanation: "Scalability is the capability to increase capacity to handle greater load. Elasticity extends this by also automatically shrinking capacity when it's no longer needed, so you only pay for what's required." },
  { id: 15, domain: "concepts", question: "An architect designs a system so that if one component fails, other components can continue operating independently because they communicate through a message queue rather than direct calls. Which design principle does this illustrate?", options: ["Loose coupling", "Vertical scaling", "Economies of scale", "Consolidated billing"], answer: 0, explanation: "Loose coupling reduces interdependencies between components, so a failure or change in one component has minimal impact on others — often implemented using queues or APIs instead of direct, tight integrations." },
  { id: 16, domain: "concepts", question: "A company deploys its application across multiple Availability Zones within a Region so that if one Availability Zone experiences an outage, the application continues to serve users from another. Which design principle does this demonstrate?", options: ["Designing for high availability", "Vertical scaling", "Capital expenditure reduction", "Consolidated billing"], answer: 0, explanation: "Distributing resources across multiple Availability Zones is a core design principle for achieving high availability, since it removes single points of failure." },
  { id: 17, domain: "concepts", question: "What is the difference between high availability and fault tolerance?", options: ["High availability aims to minimize downtime by design, while a fault-tolerant system continues operating with no noticeable disruption even when a component fails", "High availability guarantees zero downtime, while fault tolerance allows extended downtime", "Fault tolerance only applies to networking, while high availability only applies to storage", "There is no meaningful distinction between the two terms"], answer: 0, explanation: "High availability minimizes downtime through redundancy and automation, while fault tolerance goes further so a failure causes no observable impact to end users, typically at higher cost." },
  { id: 18, domain: "concepts", question: "Instead of scaling a single database server to a larger instance size, an architect adds more database read replicas to distribute the load across several smaller instances. Which scaling approach is this?", options: ["Horizontal scaling", "Vertical scaling", "Elastic scaling only", "Manual scaling only"], answer: 0, explanation: "Horizontal scaling (scaling out) adds more instances to share the load, whereas vertical scaling (scaling up) increases the size/power of a single instance." },
  { id: 19, domain: "concepts", question: "A startup chooses AWS instead of building its own data center so it can launch a new product globally within days rather than months. Which cloud benefit is the company primarily taking advantage of?", options: ["Increased speed and agility", "Consolidated billing", "Encryption at rest", "Fault tolerance"], answer: 0, explanation: "Cloud computing dramatically increases agility by removing the need to procure, rack, and configure physical hardware, letting teams experiment and deploy much faster." },
  { id: 20, domain: "concepts", question: "A company that previously had to guess its infrastructure capacity needs months in advance, often over-provisioning 'just in case,' moves to AWS. Which benefit does this address?", options: ["Stop guessing capacity", "Vendor lock-in", "Loose coupling", "Consolidated billing"], answer: 0, explanation: "One of AWS's core benefits is that you no longer need to guess your infrastructure capacity needs in advance — you can scale up or down as demand actually changes." },
  { id: 21, domain: "concepts", question: "'Undifferentiated heavy lifting' refers to which of the following concepts in cloud computing?", options: ["The routine IT infrastructure tasks (like racking servers or managing data centers) that don't differentiate a business from its competitors, which AWS takes care of", "The process of lifting and shifting an application without any modification", "A pricing model where you pay more for heavier workloads", "A security control that restricts access to EC2 instances"], answer: 0, explanation: "Undifferentiated heavy lifting describes the generic infrastructure work every company must do but that doesn't create competitive advantage. AWS handles this so customers can focus on what makes their business unique." },
  { id: 22, domain: "concepts", question: "Which of the following is an example of AWS's global infrastructure improving application performance for end users?", options: ["Serving content from an edge location or Region closer to the end user to reduce latency", "Encrypting data using AWS KMS", "Applying an IAM policy with least privilege", "Enabling MFA for the root account"], answer: 0, explanation: "AWS's globally distributed Regions and edge locations let companies place infrastructure and cached content physically closer to end users, which reduces latency and improves performance." },
  { id: 23, domain: "concepts", question: "A company wants to design a system with no single point of failure so a hardware failure in one location does not take down the entire application. Which core design principle is this?", options: ["Designing for failure", "Vertical scaling only", "Capital expenditure planning", "Consolidated billing"], answer: 0, explanation: "'Design for failure' means assuming that any individual component can fail and building redundancy so the overall system keeps functioning." },
  { id: 24, domain: "concepts", question: "Which of these best represents the idea captured by the phrase 'focus on your business, not your infrastructure' when discussing cloud economics?", options: ["AWS manages the undifferentiated heavy lifting of infrastructure so customers can focus engineering effort on their core product", "AWS requires customers to build and manage their own physical data centers", "AWS charges a flat annual fee regardless of usage", "AWS restricts customers to a single Region for all workloads"], answer: 0, explanation: "By offloading data center operations, hardware maintenance, and infrastructure management to AWS, customers can dedicate more time and resources to building differentiated products." },
  { id: 25, domain: "concepts", question: "A retailer notices its website traffic multiplies 10x during a holiday sale and drops back to normal the next week. Which combination of cloud characteristics allows the retailer to handle this without wasting money the rest of the year?", options: ["Elasticity and pay-as-you-go pricing", "Consolidated billing and Reserved Instances only", "Vertical scaling and CapEx investment", "Loose coupling and the shared responsibility model"], answer: 0, explanation: "Elasticity lets compute capacity automatically grow for the sale and shrink afterward, and pay-as-you-go pricing ensures the retailer is billed only for the resources it actually used." },

  // ── DOMAIN 2: SECURITY AND COMPLIANCE (30%) ─────────────────────────────────
  { id: 26, domain: "security", question: "Under the AWS shared responsibility model, which of the following is AWS always responsible for?", options: ["Security OF the cloud, including the physical security of data centers and the underlying host infrastructure", "Configuring security groups for a customer's EC2 instances", "Patching the guest operating system of a customer's EC2 instance", "Managing IAM users and permissions within a customer's account"], answer: 0, explanation: "AWS is responsible for 'security of the cloud' — protecting the infrastructure that runs all AWS services, including hardware, software, networking, and facilities." },
  { id: 27, domain: "security", question: "Under the AWS shared responsibility model, which task is the customer's responsibility rather than AWS's?", options: ["Configuring security groups and patching the guest operating system on their EC2 instances", "Maintaining the physical security of AWS data centers", "Patching the hypervisor that hosts EC2 instances", "Decommissioning old physical storage devices"], answer: 0, explanation: "Customers are responsible for 'security in the cloud,' which includes guest OS patching, network and firewall configuration, and identity and access management for their own resources." },
  { id: 28, domain: "security", question: "For a managed service like Amazon RDS, how does the division of responsibility differ from an unmanaged service like Amazon EC2?", options: ["AWS takes on more operational responsibility for managed services, such as patching the underlying database engine, while the customer still manages access control and data", "The customer is responsible for everything for both managed and unmanaged services", "AWS takes on no additional responsibility for managed services", "Managed services eliminate the shared responsibility model entirely"], answer: 0, explanation: "For abstracted/managed services such as RDS, AWS operates the underlying infrastructure and platform (e.g., patching the DB engine), while the customer remains responsible for things like access management and data." },
  { id: 29, domain: "security", question: "Which AWS Identity and Access Management (IAM) entity represents a single person or application that interacts with AWS?", options: ["IAM user", "IAM group", "IAM role", "IAM policy"], answer: 0, explanation: "An IAM user is an identity with long-term credentials representing a person or application that needs to interact with AWS resources." },
  { id: 30, domain: "security", question: "What is the primary purpose of an IAM group?", options: ["To make it easier to manage permissions for multiple IAM users at once by attaching policies to the group instead of each user", "To provide temporary security credentials to an application", "To encrypt data stored in Amazon S3", "To log all API calls made in an AWS account"], answer: 0, explanation: "IAM groups let administrators attach a policy once to the group, and every user added to that group automatically inherits those permissions, simplifying permission management." },
  { id: 31, domain: "security", question: "An application running on an EC2 instance needs to access an S3 bucket without embedding long-term access keys in its code. What is the recommended way to grant this access?", options: ["Attach an IAM role to the EC2 instance that grants the necessary permissions", "Hard-code the root user's access key and secret key into the application", "Create an IAM group and give the EC2 instance a username and password", "Disable IAM entirely for that instance"], answer: 0, explanation: "IAM roles provide temporary security credentials that can be assumed by an EC2 instance (or other AWS service), avoiding the security risk of embedding long-term credentials in code." },
  { id: 32, domain: "security", question: "What is an IAM policy?", options: ["A JSON document that defines permissions, specifying what actions are allowed or denied on which resources", "A physical security certification for AWS data centers", "A billing report showing monthly AWS spend", "A network firewall rule attached to a subnet"], answer: 0, explanation: "IAM policies are JSON documents attached to users, groups, or roles that explicitly define which actions are allowed or denied on specified AWS resources." },
  { id: 33, domain: "security", question: "Which security control requires a user to provide a second piece of evidence, such as a code from an authenticator app, in addition to their password when signing in?", options: ["Multi-factor authentication (MFA)", "IAM role assumption", "Security group rule", "AWS Config rule"], answer: 0, explanation: "Multi-factor authentication (MFA) adds an extra layer of protection by requiring a time-based one-time passcode or hardware token in addition to a username and password." },
  { id: 34, domain: "security", question: "Which of the following is an AWS best practice regarding the AWS account root user?", options: ["Enable MFA on the root user and avoid using it for everyday tasks, creating IAM users with appropriate permissions instead", "Share the root user credentials with the entire development team for convenience", "Use the root user for all daily administrative tasks since it has full permissions", "Disable the root user account entirely so no one can ever log in"], answer: 0, explanation: "AWS recommends locking away root user credentials, enabling MFA on the root user, and creating individual IAM users (or roles) with least-privilege permissions for day-to-day work." },
  { id: 35, domain: "security", question: "What does the principle of least privilege mean in the context of IAM?", options: ["Granting only the permissions required to perform a specific task, and no more", "Granting administrator access to every new IAM user by default", "Giving all users the same set of permissions for consistency", "Removing the need for any permissions checks on internal AWS accounts"], answer: 0, explanation: "The principle of least privilege means users and roles should be granted only the minimum permissions necessary to perform their required tasks, reducing security risk." },
  { id: 36, domain: "security", question: "A customer needs to provide auditors with AWS's compliance reports and certifications, such as SOC reports or ISO certifications, to satisfy a regulatory requirement. Which AWS service should they use?", options: ["AWS Artifact", "AWS Config", "Amazon Inspector", "AWS Shield"], answer: 0, explanation: "AWS Artifact is a self-service portal for on-demand access to AWS's compliance reports and select online agreements, useful for audits and regulatory requirements." },
  { id: 37, domain: "security", question: "Which AWS service continuously assesses, audits, and evaluates the configurations of your AWS resources against desired configuration rules?", options: ["AWS Config", "AWS Artifact", "AWS Trusted Advisor", "AWS Organizations"], answer: 0, explanation: "AWS Config records and evaluates the configuration of your AWS resources over time, letting you check compliance against defined rules and see configuration history." },
  { id: 38, domain: "security", question: "A company wants a service that uses machine learning to continuously monitor for malicious or unauthorized behavior, such as unusual API calls or potentially compromised instances, across their AWS accounts. Which service fits this need?", options: ["Amazon GuardDuty", "AWS Artifact", "Amazon Macie", "AWS Shield"], answer: 0, explanation: "Amazon GuardDuty is a threat detection service that uses machine learning and threat intelligence to continuously monitor for malicious activity and unauthorized behavior." },
  { id: 39, domain: "security", question: "Which AWS service automatically discovers software vulnerabilities and unintended network exposure on Amazon EC2 instances and container images?", options: ["Amazon Inspector", "Amazon Macie", "AWS Shield", "AWS WAF"], answer: 0, explanation: "Amazon Inspector automatically scans EC2 instances and container images for software vulnerabilities and unintended network exposure." },
  { id: 40, domain: "security", question: "A company stores large amounts of customer data in Amazon S3 and wants to automatically discover and protect sensitive data, such as personally identifiable information (PII). Which service should they use?", options: ["Amazon Macie", "AWS Shield", "AWS WAF", "AWS Config"], answer: 0, explanation: "Amazon Macie uses machine learning and pattern matching to discover, classify, and help protect sensitive data such as PII stored in Amazon S3." },
  { id: 41, domain: "security", question: "Which AWS service provides a comprehensive view of an account's security posture by aggregating and prioritizing findings from services like GuardDuty, Inspector, and Macie?", options: ["AWS Security Hub", "AWS Artifact", "AWS Organizations", "AWS Trusted Advisor"], answer: 0, explanation: "AWS Security Hub aggregates, organizes, and prioritizes security findings and alerts from multiple AWS services and partner tools into a single dashboard." },
  { id: 42, domain: "security", question: "Which AWS service is specifically designed to protect applications against Distributed Denial of Service (DDoS) attacks?", options: ["AWS Shield", "AWS WAF", "Amazon GuardDuty", "AWS KMS"], answer: 0, explanation: "AWS Shield provides protection against DDoS attacks. AWS Shield Standard is automatically included at no extra cost, while AWS Shield Advanced provides enhanced protection for an additional fee." },
  { id: 43, domain: "security", question: "A company wants to block common web exploits, such as SQL injection and cross-site scripting, from reaching their web application. Which AWS service should they configure?", options: ["AWS WAF (Web Application Firewall)", "AWS Shield Standard", "Amazon Macie", "AWS KMS"], answer: 0, explanation: "AWS WAF lets you create rules to filter and monitor HTTP/HTTPS requests, blocking common web exploits like SQL injection and cross-site scripting before they reach your application." },
  { id: 44, domain: "security", question: "Which AWS service makes it easy to create and control the cryptographic keys used to encrypt data across AWS services?", options: ["AWS Key Management Service (KMS)", "AWS Shield", "AWS WAF", "Amazon Inspector"], answer: 0, explanation: "AWS KMS is a managed service for creating and controlling the encryption keys used to encrypt data across a wide range of AWS services and applications." },
  { id: 45, domain: "security", question: "What does 'encryption at rest' protect?", options: ["Data stored on disk, such as in an S3 bucket or an EBS volume, so it is unreadable without the correct decryption key", "Data while it travels between a client and a server over the network", "Only data stored in a customer's on-premises data center", "Data that has already been deleted"], answer: 0, explanation: "Encryption at rest protects data that is stored (persisted) on a storage medium, ensuring that if the underlying storage is accessed without authorization, the data remains unreadable." },
  { id: 46, domain: "security", question: "What does 'encryption in transit' protect against?", options: ["Data being intercepted or read by unauthorized parties while it travels across a network, typically using protocols like TLS/SSL", "Unauthorized access to data after it has been written to disk", "Physical theft of a hard drive from a data center", "Malware infecting an EC2 instance"], answer: 0, explanation: "Encryption in transit (commonly using TLS/SSL) protects data as it moves between systems over a network, preventing eavesdropping or tampering." },
  { id: 47, domain: "security", question: "Which statement about AWS Shield Standard is correct?", options: ["It is automatically enabled for all AWS customers at no additional cost and protects against common, most frequently occurring network and transport layer DDoS attacks", "It must be purchased separately and configured manually for every resource", "It only protects Amazon S3 buckets", "It replaces the need for IAM entirely"], answer: 0, explanation: "AWS Shield Standard is automatically included for all AWS customers at no extra charge and provides protection against common, most frequently occurring DDoS attacks." },
  { id: 48, domain: "security", question: "A security team needs to grant a third-party auditor temporary, limited access to specific AWS resources without creating a permanent IAM user for them. What is the best approach?", options: ["Create an IAM role with the required permissions that the auditor can assume for a limited time", "Share the root user credentials with the auditor", "Create an IAM user with administrator access and never rotate the password", "Disable IAM policies for the duration of the audit"], answer: 0, explanation: "IAM roles are ideal for granting temporary, scoped access to external parties or services, since they issue short-lived credentials rather than permanent ones." },
  { id: 49, domain: "security", question: "An organization notices that its AWS account root user has never had MFA enabled and is used for daily logins by multiple employees. What is the most important corrective action?", options: ["Enable MFA on the root user, stop using it for daily tasks, and create individual IAM users with least-privilege permissions for each employee", "Delete the AWS account and create a new one", "Share the root password more widely so everyone has access", "Disable IAM entirely since it is optional"], answer: 0, explanation: "Best practice is to secure the root user with MFA, avoid routine use of it, and give each employee an individual IAM identity scoped to only the permissions they need." },
  { id: 50, domain: "security", question: "A company must prove to a regulator that AWS data centers meet certain physical security and compliance standards. Which resource should they consult first?", options: ["AWS Artifact, to download relevant compliance reports and certifications", "AWS Trusted Advisor, to check cost optimization", "Amazon CloudWatch, to review performance metrics", "AWS Budgets, to review spending limits"], answer: 0, explanation: "AWS Artifact provides on-demand access to AWS's compliance documentation, including audit artifacts like ISO certifications and SOC reports." },
  { id: 51, domain: "security", question: "A security engineer wants to automatically detect if an S3 bucket has been unintentionally made public and continuously evaluate whether it stays compliant with the company's configuration standards. Which service is best suited for this?", options: ["AWS Config", "Amazon Macie", "AWS Shield", "AWS Artifact"], answer: 0, explanation: "AWS Config continuously monitors and records AWS resource configurations, letting you create rules (like requiring S3 buckets to remain private) and get notified of non-compliant resources." },
  { id: 52, domain: "security", question: "Which of the following best differentiates a security group from a network ACL (NACL) in a VPC?", options: ["A security group operates at the instance level and is stateful, while a network ACL operates at the subnet level and is stateless", "A security group operates at the subnet level and a network ACL operates at the instance level", "Security groups can only deny traffic, while NACLs can only allow traffic", "There is no difference; they are the same feature with two names"], answer: 0, explanation: "Security groups act as a virtual firewall at the instance level and are stateful (return traffic is automatically allowed), while network ACLs act at the subnet level and are stateless (return traffic must be explicitly allowed)." },
  { id: 53, domain: "security", question: "Which AWS service would best help a company identify unencrypted, publicly exposed sensitive customer data stored in Amazon S3 buckets across many accounts?", options: ["Amazon Macie", "AWS Shield Advanced", "AWS WAF", "Amazon Route 53"], answer: 0, explanation: "Amazon Macie is purpose-built to discover and classify sensitive data, such as PII, in Amazon S3, and can flag buckets that are publicly accessible or unencrypted." },
  { id: 54, domain: "security", question: "Which of these best describes AWS Organizations' role in account governance?", options: ["It lets a company centrally manage and apply policies across multiple AWS accounts as the company grows, alongside consolidated billing", "It encrypts data across all AWS accounts automatically", "It provides 24/7 technical phone support", "It automatically remediates security group misconfigurations"], answer: 0, explanation: "AWS Organizations lets you centrally manage multiple AWS accounts, apply service control policies (SCPs) across them, and consolidate billing, which supports broader account governance and access control." },
  { id: 55, domain: "security", question: "A developer accidentally commits AWS access keys to a public code repository. What is the most urgent action to take?", options: ["Immediately deactivate/rotate the exposed access keys and issue new ones", "Wait to see if the keys are misused before taking action", "Change the account's billing address", "Enable AWS Artifact"], answer: 0, explanation: "Exposed access keys should be deactivated and rotated immediately to prevent unauthorized use, since anyone who has them can potentially access the account's resources." },
  { id: 56, domain: "security", question: "Which statement correctly distinguishes AWS Shield Advanced from AWS Shield Standard?", options: ["Shield Advanced is a paid service providing enhanced DDoS protection, near real-time visibility, and access to the DDoS Response Team (DRT), while Shield Standard is included free for all customers", "Shield Standard costs more than Shield Advanced but offers fewer features", "Shield Advanced is only available for Amazon S3, while Shield Standard covers EC2", "There is no paid tier of AWS Shield; both are free"], answer: 0, explanation: "AWS Shield Standard is automatically included at no cost and defends against common DDoS attacks. AWS Shield Advanced is a paid offering with more comprehensive protection, detailed attack diagnostics, and support from the AWS DDoS Response Team." },

  // ── DOMAIN 3: CLOUD TECHNOLOGY AND SERVICES (34%) ───────────────────────────
  { id: 57, domain: "technology", question: "Which AWS service provides resizable virtual servers in the cloud, giving customers full control over the operating system and installed software?", options: ["Amazon EC2", "Amazon S3", "AWS Lambda", "Amazon RDS"], answer: 0, explanation: "Amazon Elastic Compute Cloud (EC2) provides resizable virtual machines (instances) in the cloud, where the customer manages the OS and applications." },
  { id: 58, domain: "technology", question: "A company runs a workload with steady, predictable usage over a 1- or 3-year period and wants to reduce compute costs compared to On-Demand pricing. Which EC2 pricing model is most appropriate?", options: ["Reserved Instances or Savings Plans", "Spot Instances", "On-Demand Instances", "Dedicated Hosts only"], answer: 0, explanation: "Reserved Instances and Savings Plans offer significant discounts (up to around 72%) compared to On-Demand pricing in exchange for a 1- or 3-year commitment, ideal for steady, predictable workloads." },
  { id: 59, domain: "technology", question: "Which EC2 pricing model offers the largest discount but can be interrupted by AWS with short notice when the capacity is needed elsewhere?", options: ["Spot Instances", "On-Demand Instances", "Reserved Instances", "Savings Plans"], answer: 0, explanation: "Spot Instances let you take advantage of unused EC2 capacity at steep discounts (up to 90% off On-Demand), but AWS can reclaim that capacity with a two-minute interruption notice, making them best for fault-tolerant, flexible workloads." },
  { id: 60, domain: "technology", question: "A batch-processing job that can tolerate interruptions and be resumed later is a good fit for which EC2 pricing model to minimize cost?", options: ["Spot Instances", "On-Demand Instances", "Reserved Instances", "Dedicated Hosts"], answer: 0, explanation: "Spot Instances are well suited for fault-tolerant, flexible workloads such as batch processing, big data analysis, and CI/CD, since interruptions can be tolerated in exchange for a much lower price." },
  { id: 61, domain: "technology", question: "Which EC2 pricing model requires no upfront commitment and charges by the second (or hour) for compute capacity, making it ideal for short-term, unpredictable workloads?", options: ["On-Demand Instances", "Reserved Instances", "Spot Instances", "Savings Plans"], answer: 0, explanation: "On-Demand Instances let you pay for compute capacity by the hour or second with no long-term commitments, ideal for applications with short-term, spiky, or unpredictable workloads." },
  { id: 62, domain: "technology", question: "A flexible pricing model provides savings similar to Reserved Instances in exchange for a commitment to a consistent amount of usage (measured in $/hour) over a 1- or 3-year term, applicable across instance families and even serverless compute services. What is this model called?", options: ["Savings Plans", "Spot Instances", "Dedicated Hosts", "On-Demand Instances"], answer: 0, explanation: "Savings Plans offer lower prices in exchange for committing to a consistent amount of compute usage, and are more flexible than Reserved Instances because they can apply across instance types, sizes, and even Fargate/Lambda usage." },
  { id: 63, domain: "technology", question: "Which AWS service lets developers run code in response to events without provisioning or managing any servers, charging only for the compute time consumed?", options: ["AWS Lambda", "Amazon EC2", "Amazon Lightsail", "Amazon EKS"], answer: 0, explanation: "AWS Lambda is a serverless compute service that runs code in response to triggers/events, automatically managing the underlying compute resources, and bills only for the actual compute time used." },
  { id: 64, domain: "technology", question: "A team wants to quickly deploy a web application by simply uploading their code, while AWS automatically handles the underlying capacity provisioning, load balancing, and scaling. Which service best fits this need?", options: ["AWS Elastic Beanstalk", "Amazon EC2", "AWS Lambda", "AWS Direct Connect"], answer: 0, explanation: "AWS Elastic Beanstalk is an orchestration service that automatically handles deployment details like capacity provisioning, load balancing, and auto scaling, letting developers focus on their code." },
  { id: 65, domain: "technology", question: "Which AWS service is a fully managed container orchestration service, built specifically as AWS's own native offering for running Docker containers?", options: ["Amazon Elastic Container Service (ECS)", "Amazon Elastic Kubernetes Service (EKS)", "AWS Lambda", "Amazon Lightsail"], answer: 0, explanation: "Amazon ECS is AWS's native container orchestration service for running and scaling Docker containers, without needing to install or operate your own container orchestration software." },
  { id: 66, domain: "technology", question: "A company already has expertise managing Kubernetes and wants a managed AWS service that runs Kubernetes without them having to install and operate the Kubernetes control plane themselves. Which service should they choose?", options: ["Amazon Elastic Kubernetes Service (EKS)", "Amazon ECS", "AWS Lambda", "Amazon Lightsail"], answer: 0, explanation: "Amazon EKS is a managed service for running Kubernetes on AWS, handling the availability and scalability of the Kubernetes control plane." },
  { id: 67, domain: "technology", question: "A small business owner wants the simplest possible way to launch a website with a virtual private server, storage, and networking bundled into one low, predictable monthly price, without needing deep cloud expertise. Which service is designed for this?", options: ["Amazon Lightsail", "Amazon EC2", "AWS Direct Connect", "Amazon Redshift"], answer: 0, explanation: "Amazon Lightsail provides an easy way to launch simple workloads, such as websites or small applications, with virtual servers, storage, and networking bundled into simple, predictable pricing plans." },
  { id: 68, domain: "technology", question: "Which Amazon S3 storage class is designed for frequently accessed data and offers the highest availability and lowest latency, but at the highest per-GB storage cost among S3 tiers?", options: ["S3 Standard", "S3 Glacier Deep Archive", "S3 One Zone-IA", "S3 Glacier Flexible Retrieval"], answer: 0, explanation: "S3 Standard is designed for frequently accessed data, offering high durability, availability, and performance, but at a higher storage cost than infrequent-access or archive tiers." },
  { id: 69, domain: "technology", question: "A company has data that is accessed only about once a month but must be retrievable quickly when needed, and it must remain resilient even if an entire Availability Zone is lost. Which S3 storage class best fits this?", options: ["S3 Standard-Infrequent Access (S3 Standard-IA)", "S3 One Zone-IA", "S3 Glacier Deep Archive", "S3 Intelligent-Tiering"], answer: 0, explanation: "S3 Standard-IA is designed for infrequently accessed data that still needs rapid access when required, and it stores data redundantly across multiple Availability Zones like S3 Standard." },
  { id: 70, domain: "technology", question: "Which S3 storage class stores data in only a single Availability Zone, making it cheaper than S3 Standard-IA but at the cost of resilience if that AZ is destroyed?", options: ["S3 One Zone-IA", "S3 Standard", "S3 Glacier Instant Retrieval", "S3 Intelligent-Tiering"], answer: 0, explanation: "S3 One Zone-IA stores data in a single Availability Zone rather than replicating across multiple AZs, offering a lower price for infrequently accessed, re-creatable data that doesn't require multi-AZ resilience." },
  { id: 71, domain: "technology", question: "A company needs to archive compliance records for 7 years, rarely if ever accessing them, and wants the lowest possible storage cost, tolerating retrieval times of up to 12 hours. Which storage option fits best?", options: ["S3 Glacier Deep Archive", "S3 Standard", "Amazon EBS", "Amazon EFS"], answer: 0, explanation: "S3 Glacier Deep Archive is Amazon S3's lowest-cost storage class, designed for long-term data archiving that is rarely accessed, with retrieval times typically within 12 hours." },
  { id: 72, domain: "technology", question: "Which S3 feature automatically moves objects between access tiers based on changing access patterns, without requiring manual lifecycle rule tuning?", options: ["S3 Intelligent-Tiering", "S3 One Zone-IA", "S3 Transfer Acceleration", "S3 Versioning"], answer: 0, explanation: "S3 Intelligent-Tiering automatically moves objects between frequent-access and infrequent-access tiers based on usage patterns, optimizing storage costs without manual intervention." },
  { id: 73, domain: "technology", question: "Which storage service provides block-level storage volumes that must be attached to a single EC2 instance, commonly used as a virtual hard drive for that instance?", options: ["Amazon Elastic Block Store (EBS)", "Amazon S3", "Amazon EFS", "Amazon Glacier"], answer: 0, explanation: "Amazon EBS provides persistent block storage volumes for use with EC2 instances, functioning like a virtual hard disk that is typically attached to one instance at a time." },
  { id: 74, domain: "technology", question: "A company needs a shared file system that can be mounted concurrently by hundreds of Linux-based EC2 instances across multiple Availability Zones. Which service should they use?", options: ["Amazon Elastic File System (EFS)", "Amazon EBS", "Amazon S3 Glacier", "AWS Storage Gateway"], answer: 0, explanation: "Amazon EFS is a fully managed, scalable NFS file system that can be mounted concurrently by many EC2 instances across multiple Availability Zones, unlike EBS which typically attaches to one instance at a time." },
  { id: 75, domain: "technology", question: "Which AWS service provides a hybrid storage solution, allowing an on-premises application to seamlessly use AWS cloud storage through standard storage protocols like NFS or iSCSI?", options: ["AWS Storage Gateway", "Amazon S3 Transfer Acceleration", "Amazon EFS", "AWS Direct Connect"], answer: 0, explanation: "AWS Storage Gateway connects on-premises environments to AWS cloud storage, presenting cloud storage through familiar interfaces such as NFS, SMB, or iSCSI for hybrid cloud storage use cases." },
  { id: 76, domain: "technology", question: "What is an Amazon VPC (Virtual Private Cloud)?", options: ["A logically isolated section of the AWS Cloud where a customer can launch resources in a virtual network they define", "A physical data center dedicated entirely to a single customer", "A managed relational database service", "A content delivery network for static website assets"], answer: 0, explanation: "Amazon VPC lets you provision a logically isolated virtual network within AWS, where you control IP address ranges, subnets, route tables, and gateways." },
  { id: 77, domain: "technology", question: "Within a VPC, what is the primary difference between a public subnet and a private subnet?", options: ["A public subnet has a route to an internet gateway, allowing direct internet access, while a private subnet does not", "A public subnet can only host databases, while a private subnet can only host web servers", "A private subnet is always more expensive to operate than a public subnet", "There is no difference; the terms are interchangeable"], answer: 0, explanation: "A public subnet's route table includes a route to an internet gateway, allowing resources in it to communicate directly with the internet, whereas a private subnet lacks that direct route." },
  { id: 78, domain: "technology", question: "Which AWS service is a highly available and scalable Domain Name System (DNS) web service used to route end users to internet applications?", options: ["Amazon Route 53", "Amazon CloudFront", "AWS Direct Connect", "Elastic Load Balancing"], answer: 0, explanation: "Amazon Route 53 is AWS's DNS web service, used for domain registration, DNS routing, and health checking to route users to internet-facing endpoints." },
  { id: 79, domain: "technology", question: "Which AWS service is a content delivery network (CDN) that caches content at edge locations around the world to reduce latency for end users?", options: ["Amazon CloudFront", "Amazon Route 53", "AWS Direct Connect", "Amazon VPC"], answer: 0, explanation: "Amazon CloudFront is a CDN service that delivers data, videos, applications, and APIs to users with low latency by caching content at edge locations close to end users." },
  { id: 80, domain: "technology", question: "A company wants a dedicated, private network connection from its on-premises data center to AWS, bypassing the public internet for more consistent network performance. Which service should it use?", options: ["AWS Direct Connect", "Amazon Route 53", "AWS VPN CloudHub", "Amazon CloudFront"], answer: 0, explanation: "AWS Direct Connect establishes a dedicated, private network connection between an on-premises location and AWS, providing more consistent network performance than a connection over the public internet." },
  { id: 81, domain: "technology", question: "Which type of Elastic Load Balancer operates at Layer 7 (the application layer), making routing decisions based on HTTP/HTTPS content such as URL paths or headers?", options: ["Application Load Balancer (ALB)", "Network Load Balancer (NLB)", "Classic Load Balancer (CLB)", "Gateway Load Balancer"], answer: 0, explanation: "The Application Load Balancer operates at Layer 7 and can route traffic based on the content of the request, such as URL path or hostname, ideal for microservices and container-based applications." },
  { id: 82, domain: "technology", question: "Which type of Elastic Load Balancer is best suited for extremely high-performance, low-latency use cases and operates at Layer 4 (the transport layer), routing based on IP protocol data?", options: ["Network Load Balancer (NLB)", "Application Load Balancer (ALB)", "Classic Load Balancer (CLB)", "Route 53"], answer: 0, explanation: "The Network Load Balancer operates at Layer 4 and is designed to handle millions of requests per second with ultra-low latency, ideal for TCP/UDP traffic." },
  { id: 83, domain: "technology", question: "Which AWS database service is a fully managed relational database that supports engines such as MySQL, PostgreSQL, and SQL Server?", options: ["Amazon RDS", "Amazon DynamoDB", "Amazon Redshift", "Amazon Neptune"], answer: 0, explanation: "Amazon Relational Database Service (RDS) is a managed service that supports several relational database engines and handles tasks like patching, backups, and hardware provisioning." },
  { id: 84, domain: "technology", question: "A company needs a fully managed NoSQL database that delivers single-digit millisecond performance at any scale, ideal for a high-traffic mobile app's session data. Which service should it choose?", options: ["Amazon DynamoDB", "Amazon RDS", "Amazon Redshift", "Amazon Aurora"], answer: 0, explanation: "Amazon DynamoDB is a fully managed, serverless key-value/NoSQL database that delivers consistent single-digit millisecond performance at virtually any scale." },
  { id: 85, domain: "technology", question: "Which AWS service is a fully managed, petabyte-scale data warehouse designed for complex analytical queries across large datasets?", options: ["Amazon Redshift", "Amazon RDS", "Amazon DynamoDB", "Amazon ElastiCache"], answer: 0, explanation: "Amazon Redshift is a fully managed data warehouse service optimized for online analytical processing (OLAP) and complex queries across large volumes of data, commonly used for business intelligence." },
  { id: 86, domain: "technology", question: "Which AWS relational database engine is described by AWS as providing up to 5x the throughput of standard MySQL and up to 3x that of standard PostgreSQL, while remaining compatible with those engines?", options: ["Amazon Aurora", "Amazon Redshift", "Amazon DynamoDB", "Amazon Neptune"], answer: 0, explanation: "Amazon Aurora is a MySQL- and PostgreSQL-compatible relational database built for the cloud, offering significantly higher throughput and performance than standard versions of those engines." },
  { id: 87, domain: "technology", question: "What is an AWS Region?", options: ["A physical, geographically separate location that contains multiple, isolated Availability Zones", "A single physical data center building", "A logical grouping of IAM users", "A synonym for an edge location"], answer: 0, explanation: "An AWS Region is a physical geographic area containing multiple, isolated Availability Zones connected via low-latency links, letting customers choose where to run workloads for compliance, latency, or cost reasons." },
  { id: 88, domain: "technology", question: "What is an Availability Zone (AZ)?", options: ["One or more discrete data centers within an AWS Region, each with independent power, cooling, and networking, designed to be isolated from failures in other AZs", "A single server rack inside a data center", "A worldwide network of caching servers used by CloudFront", "A billing construct used to group AWS accounts"], answer: 0, explanation: "Availability Zones are physically separate data centers within a Region, engineered to be isolated from failures in other AZs while being connected through low-latency links, enabling high availability architectures." },
  { id: 89, domain: "technology", question: "What is the purpose of AWS edge locations?", options: ["To cache content closer to end users for services like Amazon CloudFront, reducing latency for content delivery", "To host the primary compute resources for EC2 instances", "To store long-term compliance and audit reports", "To serve as the primary billing location for an AWS account"], answer: 0, explanation: "Edge locations are sites used by CloudFront (and Route 53) to cache copies of content closer to end users around the world, reducing latency for content delivery." },
  { id: 90, domain: "technology", question: "Which service provides logs, metrics, and alarms to monitor the performance and operational health of AWS resources and applications?", options: ["Amazon CloudWatch", "AWS CloudTrail", "AWS Trusted Advisor", "AWS Config"], answer: 0, explanation: "Amazon CloudWatch collects and tracks metrics, collects and monitors log files, and sets alarms, giving visibility into resource utilization, application performance, and operational health." },
  { id: 91, domain: "technology", question: "Which AWS service records a history of API calls made in an account, including who made the call, when, and from where, primarily used for governance, compliance, and auditing?", options: ["AWS CloudTrail", "Amazon CloudWatch", "AWS Trusted Advisor", "AWS Config"], answer: 0, explanation: "AWS CloudTrail logs and records AWS API calls made within an account, providing an audit trail useful for security analysis, compliance auditing, and operational troubleshooting." },
  { id: 92, domain: "technology", question: "A solutions architect wants automated, real-time guidance on how to provision resources following AWS best practices for cost optimization, security, fault tolerance, and performance. Which service provides this?", options: ["AWS Trusted Advisor", "AWS CloudTrail", "Amazon CloudWatch", "AWS Config"], answer: 0, explanation: "AWS Trusted Advisor inspects your AWS environment in real time and provides recommendations across categories including cost optimization, performance, security, fault tolerance, and service limits." },

  // ── DOMAIN 4: BILLING, PRICING, AND SUPPORT (12%) ───────────────────────────
  { id: 93, domain: "billing", question: "Which AWS pricing principle describes paying only for the individual services used, for as long as they are used, with no long-term contracts required?", options: ["Pay-as-you-go", "Consolidated billing", "Reserved pricing", "Fixed-rate billing"], answer: 0, explanation: "Pay-as-you-go is a foundational AWS pricing principle: customers pay only for the compute, storage, and other resources they actually consume, without needing long-term contracts." },
  { id: 94, domain: "billing", question: "What is the AWS Free Tier?", options: ["A program that allows customers to gain hands-on experience with a limited amount of usage of certain AWS services for free, subject to specific limits", "A support plan that includes free 24/7 technical support", "A discount applied automatically to all Reserved Instance purchases", "A free upgrade to unlimited compute capacity for the first year"], answer: 0, explanation: "The AWS Free Tier offers limited free usage of certain services (some always free, some free for 12 months, and some short-term trials) so new customers can experiment at no cost within specified limits." },
  { id: 95, domain: "billing", question: "Before migrating a workload to AWS, a company wants to estimate the monthly cost of the proposed architecture. Which AWS tool is designed for this purpose?", options: ["AWS Pricing Calculator", "AWS Cost Explorer", "AWS Budgets", "AWS Trusted Advisor"], answer: 0, explanation: "The AWS Pricing Calculator lets you model the cost of AWS services before you use them, helping estimate the monthly and upfront costs of a proposed architecture." },
  { id: 96, domain: "billing", question: "Which AWS tool lets you visualize, understand, and analyze your AWS costs and usage over time, including historical spending patterns and forecasts?", options: ["AWS Cost Explorer", "AWS Pricing Calculator", "AWS Budgets", "AWS Artifact"], answer: 0, explanation: "AWS Cost Explorer provides an interactive interface to visualize, understand, and analyze historical AWS costs and usage, and to forecast future spending." },
  { id: 97, domain: "billing", question: "A finance team wants to receive an automatic alert if AWS spending is on track to exceed a set monthly threshold. Which service should they configure?", options: ["AWS Budgets", "AWS Cost Explorer", "AWS Pricing Calculator", "AWS Organizations"], answer: 0, explanation: "AWS Budgets lets you set custom cost and usage budgets and sends alerts when your actual or forecasted spend exceeds the thresholds you define." },
  { id: 98, domain: "billing", question: "A parent company has five AWS accounts for different departments and wants a single consolidated invoice while also becoming eligible for volume pricing discounts across combined usage. What AWS billing feature enables this?", options: ["Consolidated billing (via AWS Organizations)", "AWS Budgets", "AWS Free Tier", "Savings Plans"], answer: 0, explanation: "Consolidated billing, a feature of AWS Organizations, combines usage across multiple linked accounts onto a single paying account's bill, and can help accounts qualify for volume pricing discounts." },
  { id: 99, domain: "billing", question: "Which AWS Support plan is the free, default plan available to all AWS customers, providing access to account and billing support but not technical support cases?", options: ["Basic Support", "Developer Support", "Business Support", "Enterprise Support"], answer: 0, explanation: "AWS Basic Support is included automatically for every AWS account at no cost and provides customer service, documentation, and access to AWS Trusted Advisor's core checks, but not technical support cases." },
  { id: 100, domain: "billing", question: "A solo developer building a non-production application wants access to email-based technical support with response times measured in business hours, at a low monthly cost. Which AWS Support plan best matches this need?", options: ["Developer Support", "Business Support", "Enterprise Support", "Basic Support"], answer: 0, explanation: "Developer Support is aimed at individuals experimenting with or testing on AWS, offering email access to Cloud Support Associates during business hours, but without 24/7 or production-focused response guarantees." },
  { id: 101, domain: "billing", question: "A company runs production workloads on AWS and needs 24/7 phone, chat, and email access to technical support with fast response times for production system down issues. Which support plan is designed for this?", options: ["Business Support", "Developer Support", "Basic Support", "None; this requires a custom contract"], answer: 0, explanation: "Business Support provides 24/7 access to Cloud Support Engineers via phone, chat, and email, with fast response times, including under one hour for production system down issues." },
  { id: 102, domain: "billing", question: "Which AWS Support plan includes a designated Technical Account Manager (TAM) who provides proactive guidance and works with the customer to plan and build on AWS?", options: ["Enterprise Support", "Business Support", "Developer Support", "Basic Support"], answer: 0, explanation: "AWS Enterprise Support (and Enterprise On-Ramp) includes a Technical Account Manager who provides proactive, personalized guidance and acts as a primary point of contact for support and architecture reviews." },
  { id: 103, domain: "billing", question: "What does Total Cost of Ownership (TCO) refer to when comparing on-premises infrastructure to AWS Cloud?", options: ["An estimate of all direct and indirect costs of owning and operating infrastructure, including hardware, power, staffing, and facilities, compared against the cost of using AWS", "The one-time cost of migrating an application to AWS", "The monthly bill generated by AWS Cost Explorer", "A fixed annual fee charged by AWS for using more than one service"], answer: 0, explanation: "TCO analysis looks beyond just the sticker price of hardware to include costs like power, cooling, physical space, and IT staff, providing a fuller comparison between on-premises and cloud options." },
  { id: 104, domain: "billing", question: "A company runs a nightly batch analytics job that can be interrupted and restarted without issue, and they want to minimize compute costs for this workload. Which pricing approach offers the greatest savings?", options: ["Spot Instances", "On-Demand Instances at full price", "A 1-year Reserved Instance with no flexibility", "Enterprise Support plan upgrade"], answer: 0, explanation: "Because the batch job tolerates interruption, Spot Instances offer the deepest discount (up to 90% off On-Demand) for this type of fault-tolerant, flexible workload." },
  { id: 105, domain: "billing", question: "A rapidly growing e-commerce company runs mission-critical production workloads around the clock and wants proactive architectural guidance plus guaranteed fast response times, including a dedicated Technical Account Manager. Which AWS Support plan should they select?", options: ["Enterprise Support", "Basic Support", "Developer Support", "Business Support"], answer: 0, explanation: "Enterprise Support is designed for mission-critical, production workloads at scale, providing a Technical Account Manager, proactive guidance, and the fastest response time commitments (e.g., 15 minutes for business-critical system down)." },
];

export default questions;
